import 'package:flutter/material.dart';import 'package:platform_core_frontend/features/super_admin/data/super_admin_repository.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_masjid_request_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/widgets_common.dart';import 'package:platform_core_frontend/shared/widgets/loading_view.dart';
class AdminMasjidRequestDetailScreen extends StatelessWidget{const AdminMasjidRequestDetailScreen({super.key,required this.id,this.initial});final String id;final AdminMasjidRequestModel? initial;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Request Details')),body:FutureBuilder(future:SuperAdminRepository().getMasjidRequest(id),initialData: initial,builder:(c,s){if(!s.hasData)return const LoadingView();final r=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[AdminStatusChip(r.status),InfoRow('Masjid',r.masjidName),InfoRow('Requester',r.requesterName),InfoRow('Phone',r.requesterPhone),InfoRow('Email',r.requesterEmail),InfoRow('Location',[r.village,r.city,r.district,r.state].where((e)=>e!=null).join(', ')),InfoRow('Address',r.address),InfoRow('Contact',r.contactNo),InfoRow('Imam',r.imamName),InfoRow('Imam Phone',r.imamPhone),InfoRow('Reason',r.rejectionReason),InfoRow('Created',r.createdAt)]);}));}
